var snFieldList = findDictionaryReferences();

function userCheck (gu, bu, snFieldList) {

    var fieldList = snFieldList[i];
    var tblName = fieldList.name;
    var fldName = fieldList.element;

    var badUser = bu.sys_id;
    var goodUser = gu.sys_id;

    for (var i = 0; i < snFieldList.length; i++) {
        var findBU = new GlideRecord(tblName);
        findBU.addQuery(fldName, badUser);
        findBU.addQuery('active', true);
        findBU.query();

        while (findBU.next()){
            findBU.setValue(fldName, goodUser);
            findBU.setWorkflow(false);
            findBU.autoSysFields(false);
            findBU.update();
        }
    }
}

function findDictionaryReferences() {
    var snTables = ["incident", "change_request", "change_task", "sc_req_item", "sc_request", "sc_task", "sysapproval_approver"];
    //var snTables = ["incident"];


    var userRefArr = [];
    //Query dictionary table for Task and CMDB Tables
    var dict = new GlideRecord('sys_dictionary');
    //dict.addQuery('name', 'IN', snTables);
    //dev SysID for User table
    //dict.addEncodedQuery('reference=sys_user^nameIN'+snTables);  //sys_idIN28dd2c721bef8ad0c73ceca5604bcb32
    dict.addQuery('reference', 'sys_user');
    dict.addQuery('name', 'IN', snTables);
    //dict.addQuery('name', 'DOESNOTCONTAIN', 'x_g_dh5');
    //dict.addQuery('name', 'DOESNOTCONTAIN', 'u_');
    //dict.addQuery();
    dict.setLimit(50);
    dict.query();
    while (dict.next()) {

        var tblName = dict.getValue('name');
        var fldName = dict.getValue('element');

        userRefArr.push({"table": tblName, "element": fldName});

        //gr.setAutoSys(false);
        //gr.setWorkflow(false);

    }

    return userRefArr;
}
